<script setup>import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {api,upload,toast} from '../core';const router=useRouter(),busy=ref(false),uploading=ref(false),error=ref(''),form=reactive({name:'',category:'cat',province:'',region:'',breed:'未知',description:'',image:'',phone:'',wechat:'',email:''});async function photo(e){if(!e.target.files[0])return;uploading.value=true;try{form.image=await upload(e.target.files[0])}catch(e){toast(e.message,true)}finally{uploading.value=false}}async function save(){busy.value=true;error.value='';try{const p=await api('/pets','POST',form);toast('领养信息已发布');router.push('/pets/'+p.id)}catch(e){error.value=e.message}finally{busy.value=false}};</script><template><section class="shell section narrow"><p class="eyebrow">HELP A LITTLE FRIEND FIND HOME</p><h1>为它，寻找一个家。</h1><p class="muted">请提供真实、完整的信息，并确保你能够安排宠物交接。</p><form class="panel form-stack" @submit.prevent="save"><label>宠物照片<input type="file" accept="image/jpeg,image/png" @change="photo"><span class="hint">JPEG / PNG，最大 8MB；请使用你有权分享的照片。</span></label><p v-if="uploading">图片正在上传…</p><img v-if="form.image" :src="form.image" class="upload-preview" alt="已上传的宠物照片"><div class="form-grid"><label>宠物名字<input v-model="form.name" maxlength="80" required placeholder="它叫什么名字？"></label><label>类别<select v-model="form.category"><option value="cat">猫咪</option><option value="dog">狗狗</option></select></label><label>省份<input v-model="form.province" required maxlength="30" placeholder="如：湖北省"></label><label>城市 / 区县<input v-model="form.region" required maxlength="120" placeholder="如：武汉市洪山区"></label><label>品种<input v-model="form.breed" required maxlength="80"></label></div><label>关于它与送养要求<textarea v-model="form.description" maxlength="1000" rows="5" placeholder="分享它的性格、日常习惯和需要注意的事情…"></textarea></label><h3>联系方式 <small class="muted">至少填写一种</small></h3><div class="form-grid"><label>电话<input v-model="form.phone" maxlength="32"></label><label>微信<input v-model="form.wechat" maxlength="40"></label><label>邮箱<input v-model="form.email" maxlength="100" type="email"></label></div><p class="hint">联系方式对登录用户开放；进入交接后仅对当事人开放。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="btn" :disabled="busy||uploading||!form.image">{{busy?'正在发布…':'发布领养信息'}}</button></form></section></template>
